import{_ as s,o as e,c as a,a2 as i}from"./chunks/framework.DqtRuLLf.js";const k=JSON.parse('{"title":"01. 介绍","description":"","frontmatter":{},"headers":[],"relativePath":"01-introduction/index.md","filePath":"01-introduction/index.md","lastUpdated":1792642815000}'),n={name:"01-introduction/index.md"};function r(l,t,d,o,h,p){return e(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="_01-介绍" tabindex="-1">01. 介绍 <a class="header-anchor" href="#_01-介绍" aria-label="Permalink to &quot;01. 介绍&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">对应漫画</p><p>本章配套四格漫画：<a href="https://yzhijie.github.io/nestjs-tutorial/comics/index.html#ep-1" target="_blank" rel="noreferrer">EP.01 初识 NestJS</a>（含剧情回顾、知识点拆解、坑点清单与自测题）</p></div><blockquote><p>本章为概念章节，无独立示例入口。</p></blockquote><h2 id="nestjs-是什么" tabindex="-1">NestJS 是什么 <a class="header-anchor" href="#nestjs-是什么" aria-label="Permalink to &quot;NestJS 是什么&quot;">​</a></h2><p>NestJS 是一个用于构建<strong>高效、可扩展的服务端应用</strong>的 Node.js 框架。它使用 TypeScript 构建（同时兼容纯 JavaScript），结合了三种编程范式：</p><ul><li><strong>面向对象编程（OOP）</strong>：控制器、服务、模块都是类，职责边界清晰；</li><li><strong>函数式编程（FP）</strong>：拦截器、管道大量运用 RxJS 与纯函数思想；</li><li><strong>函数响应式编程（FRP）</strong>：RxJS 是一等公民，流式处理贯穿框架。</li></ul><p>NestJS 默认基于 <strong>Express</strong> 作为底层 HTTP 平台，也可以一行代码切换到 <strong>Fastify</strong>。框架在此之上提供了一套开箱即用的应用架构——如果你用过 Angular，会发现模块、依赖注入、装饰器这些概念几乎一模一样。</p><h2 id="为什么选择-nestjs" tabindex="-1">为什么选择 NestJS <a class="header-anchor" href="#为什么选择-nestjs" aria-label="Permalink to &quot;为什么选择 NestJS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>痛点</th><th>NestJS 的解法</th></tr></thead><tbody><tr><td>Express/Koa 自由度过高，项目结构因人而异</td><td>提供「约定优于配置」的标准架构：模块 + 控制器 + 提供者</td></tr><tr><td>JavaScript 大型项目缺乏类型约束</td><td>全面拥抱 TypeScript，装饰器元数据驱动依赖注入</td></tr><tr><td>横切关注点（鉴权、日志、校验）散落各处</td><td>提供守卫、拦截器、管道、异常过滤器四大利器</td></tr><tr><td>依赖关系靠手动 new，测试困难</td><td>内置 IoC 容器，构造函数声明依赖，mock 替换轻而易举</td></tr><tr><td>微服务、WebSocket、GraphQL 各自为政</td><td>同一套编程模型覆盖 HTTP、WebSocket、微服务、GraphQL、CQRS</td></tr></tbody></table><h2 id="核心特性一览" tabindex="-1">核心特性一览 <a class="header-anchor" href="#核心特性一览" aria-label="Permalink to &quot;核心特性一览&quot;">​</a></h2><ul><li><strong>模块化架构</strong>：应用由模块（<code>@Module</code>）组成，支持静态模块、动态模块、全局模块；</li><li><strong>依赖注入（DI）</strong>：内置 IoC 容器，支持单例 / 瞬态 / 请求级三种作用域；</li><li><strong>请求处理管线</strong>：中间件 → 守卫 → 拦截器 → 管道 → 控制器 → 异常过滤器，职责分明；</li><li><strong>装饰器驱动</strong>：<code>@Get()</code>、<code>@Post()</code>、<code>@Injectable()</code>、<code>@UseGuards()</code> 等声明式 API；</li><li><strong>生态系统</strong>：<code>@nestjs/typeorm</code>、<code>@nestjs/jwt</code>、<code>@nestjs/config</code> 等官方模块开箱即用；</li><li><strong>CLI 工具</strong>：<code>@nestjs/cli</code> 提供项目生成、代码脚手架、构建能力。</li></ul><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><p>本教程及配套示例项目要求：</p><table tabindex="0"><thead><tr><th>依赖</th><th>版本要求</th><th>本教程实际使用</th></tr></thead><tbody><tr><td>Node.js</td><td>≥ 18</td><td>v24</td></tr><tr><td>npm</td><td>≥ 9</td><td>v11</td></tr><tr><td>TypeScript</td><td>≥ 5.0</td><td>v5.7</td></tr><tr><td>NestJS</td><td>11.x（当前最新稳定版）</td><td>^11.0.0</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">操作系统</p><p>示例在 macOS / Linux / Windows 均可运行，文档中的 curl 命令以 macOS/Linux 语法给出；Windows 用户建议使用 Git Bash 或 WSL。</p></div><h2 id="两种搭建项目的方式" tabindex="-1">两种搭建项目的方式 <a class="header-anchor" href="#两种搭建项目的方式" aria-label="Permalink to &quot;两种搭建项目的方式&quot;">​</a></h2><h3 id="方式一-nest-cli-官方推荐" tabindex="-1">方式一：Nest CLI（官方推荐） <a class="header-anchor" href="#方式一-nest-cli-官方推荐" aria-label="Permalink to &quot;方式一：Nest CLI（官方推荐）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @nestjs/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-nest-app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>CLI 会生成完整项目骨架（含 ESLint、Prettier、Jest），并提供代码生成器：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 生成模块</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> controller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 生成控制器</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 生成服务</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="方式二-手动搭建-本教程示例项目采用" tabindex="-1">方式二：手动搭建（本教程示例项目采用） <a class="header-anchor" href="#方式二-手动搭建-本教程示例项目采用" aria-label="Permalink to &quot;方式二：手动搭建（本教程示例项目采用）&quot;">​</a></h3><p>为了让你看清 Nest 应用的<strong>最小必需结构</strong>，本教程的配套示例项目没有使用 CLI 生成器，而是手工编写每个文件。一个 Nest 应用最少只需要：</p><ol><li><code>main.ts</code> —— 入口文件，用 <code>NestFactory</code> 创建应用并监听端口；</li><li>一个根模块 <code>app.module.ts</code> —— 组织应用结构；</li><li>至少一个控制器或服务 —— 处理业务；</li><li><code>tsconfig.json</code> —— 必须开启 <code>experimentalDecorators</code> 与 <code>emitDecoratorMetadata</code>（装饰器与 DI 的基石）。</li></ol><p>下一章我们将从零手写这四个文件，并把第一个应用跑起来。</p><h2 id="本教程的组织方式" tabindex="-1">本教程的组织方式 <a class="header-anchor" href="#本教程的组织方式" aria-label="Permalink to &quot;本教程的组织方式&quot;">​</a></h2><ul><li>每章聚焦一个主题，先讲概念，再给<strong>完整可运行代码</strong>，最后给出 curl 验证命令与真实期望输出；</li><li>文档中所有代码块都通过 VitePress 的代码片段导入功能<strong>直接引用示例项目源文件</strong>，保证文档与代码零偏差；</li><li>每章示例在 <code>server/src/chXX-*</code> 目录下，端口为 <code>3000 + 章节号</code>（如第 5 章为 3005）。</li></ul>`,26)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
